__all__ = ["raw_ops"]
_R = TypeVar("_R")


def _extract_arg(
    args: tuple[Tensor | TensorOperand, ...],
    kwargs: dict[str, Tensor | TensorOperand],
    index: int,
    *keys: str,
) -> Tensor | TensorOperand:
    """Extract a positional or keyword argument by index or key names.

    Args:
        args: Positional argument tuple.
        kwargs: Keyword argument mapping.
        index: Positional index to look up.
        *keys: Candidate keyword names to look up.

    Returns:
        Tensor | TensorOperand: Extracted argument or `None`.
    """
    if len(args) > index:
        return args[index]
    for k in keys:
        if k in kwargs:
            return kwargs[k]
    return None


def _unary_op(
    fn: Callable[[Tensor | TensorOperand], _R],
    args: tuple[Tensor | TensorOperand, ...],
    kwargs: dict[str, Tensor | TensorOperand],
    *keys: str,
) -> _R | None:
    """Dispatch a unary `raw_ops` call when the primary argument is provided.

    Args:
        fn: Underlying unary operation callable.
        args: Positional argument tuple.
        kwargs: Keyword argument mapping.
        *keys: Candidate keyword names for the first operand.

    Returns:
        _R | None: Operation result or `None` when called with no arguments.
    """
    val = _extract_arg(
        args,
        kwargs,
        0,
        *(
            keys
            if keys
            else ("x", "input", "features", "logits", "value", "values", "images", "filename")
        ),
    )
    return fn(val) if val is not None else None


def _binary_op(
    fn: Callable[[Tensor | TensorOperand, Tensor | TensorOperand], _R],
    args: tuple[Tensor | TensorOperand, ...],
    kwargs: dict[str, Tensor | TensorOperand],
    k0: tuple[str, ...] = ("x", "a", "input", "params", "tensor", "values", "filename", "shape"),
    k1: tuple[str, ...] = (
        "y",
        "b",
        "shape",
        "indices",
        "axis",
        "DstT",
        "dtype",
        "contents",
        "seed",
    ),
) -> _R | None:
    """Dispatch a binary `raw_ops` call when both operands are provided.

    Args:
        fn: Underlying binary operation callable.
        args: Positional argument tuple.
        kwargs: Keyword argument mapping.
        k0: Candidate keyword names for the first operand.
        k1: Candidate keyword names for the second operand.

    Returns:
        _R | None: Operation result or `None` when called without both operands.
    """
    v0 = _extract_arg(args, kwargs, 0, *k0)
    v1 = _extract_arg(args, kwargs, 1, *k1)
    return fn(v0, v1) if v0 is not None and v1 is not None else None


def _ternary_op(
    fn: Callable[[Tensor | TensorOperand, Tensor | TensorOperand, Tensor | TensorOperand], _R],
    args: tuple[Tensor | TensorOperand, ...],
    kwargs: dict[str, Tensor | TensorOperand],
    k0: tuple[str, ...] = ("input", "indices", "condition", "x"),
    k1: tuple[str, ...] = ("begin", "updates", "x", "a"),
    k2: tuple[str, ...] = ("size", "end", "shape", "y", "b"),
) -> _R | None:
    """Dispatch a ternary `raw_ops` call when all three operands are provided.

    Args:
        fn: Underlying ternary operation callable.
        args: Positional argument tuple.
        kwargs: Keyword argument mapping.
        k0: Candidate keyword names for the first operand.
        k1: Candidate keyword names for the second operand.
        k2: Candidate keyword names for the third operand.

    Returns:
        _R | None: Operation result or `None` when called without three operands.
    """
    v0 = _extract_arg(args, kwargs, 0, *k0)
    v1 = _extract_arg(args, kwargs, 1, *k1)
    v2 = _extract_arg(args, kwargs, 2, *k2)
    return fn(v0, v1, v2) if v0 is not None and v1 is not None and (v2 is not None) else None


def _do_matmul(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `MatMul` / `BatchMatMulV2` with transpose and adjoint flags.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Matrix product `Tensor` or `None`.
    """
    return _binary_op(
        lambda a, b: _linalg.matmul(
            a,
            b,
            transpose_a=bool(kwargs.get("transpose_a", False)),
            transpose_b=bool(kwargs.get("transpose_b", False)),
            adjoint_a=bool(kwargs.get("adj_x", False)),
            adjoint_b=bool(kwargs.get("adj_y", False)),
        ),
        args,
        kwargs,
    )


def _do_transpose(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `Transpose` with optional permutation argument.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Transposed `Tensor` or `None`.
    """
    perm = _extract_arg(args, kwargs, 1, "perm")
    return _unary_op(
        lambda x: _math.transpose(x, perm) if perm is not None else _math.transpose(x), args, kwargs
    )


def _do_concat_v2(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `ConcatV2` along `axis`.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Concatenated `Tensor` or `None`.
    """
    return _binary_op(lambda vals, ax: _math.concat(vals, axis=ax), args, kwargs)


def _do_pack(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `Pack` (stack) along `axis`.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Stacked `Tensor` or `None`.
    """
    return _unary_op(lambda vals: _math.stack(vals, axis=kwargs.get("axis", 0)), args, kwargs)


def _do_unpack(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> list[Tensor] | None:
    """Execute `Unpack` (unstack) along `axis`.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        list[Tensor] | None: Unstacked list of `Tensor`s or `None`.
    """
    return _unary_op(lambda val: _math.unstack(val, axis=kwargs.get("axis", 0)), args, kwargs)


def _do_strided_slice(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `StridedSlice` with optional `strides`.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Sliced `Tensor` or `None`.
    """
    strides = _extract_arg(args, kwargs, 3, "strides")
    return _ternary_op(
        lambda inp, beg, end: _math.strided_slice(inp, beg, end, strides), args, kwargs
    )


def _do_gather_v2(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `GatherV2` with optional `axis`.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Gathered `Tensor` or `None`.
    """
    axis = _extract_arg(args, kwargs, 2, "axis")
    return _binary_op(
        lambda p, idx: _math.gather(p, idx, axis=axis if axis is not None else 0), args, kwargs
    )


def _do_cast(
    args: tuple[Tensor | TensorOperand, ...], kwargs: dict[str, Tensor | TensorOperand]
) -> Tensor | None:
    """Execute `Cast` to target `DstT` dtype.

    Args:
        args: Positional operation arguments.
        kwargs: Keyword operation arguments.

    Returns:
        Tensor | None: Casted `Tensor` or `None`.
    """
    return _binary_op(lambda x, dt: _math.cast(x, dtype=dt), args, kwargs)


def _pack_raw_call(
    explicit: tuple[tuple[str, Tensor | TensorOperand], ...],
    args: tuple[Tensor | TensorOperand, ...],
    kwargs: dict[str, Tensor | TensorOperand],
) -> tuple[tuple[Tensor | TensorOperand, ...], dict[str, Tensor | TensorOperand]]:
    """Combine explicit named `raw_ops` parameters with `*args` and `**kwargs`.

    Args:
        explicit: Tuple of `(name, value)` pairs for explicit parameters.
        args: Variadic positional arguments.
        kwargs: Variadic keyword arguments.

    Returns:
        tuple[tuple[Tensor | TensorOperand, ...], dict[str, Tensor | TensorOperand]]:
            Packed `(args, kwargs)` pair.
    """
    pos: list[Tensor | TensorOperand] = [
        v for (k, v) in explicit if v is not None and not (k == "name" and isinstance(v, str))
    ]
    pos.extend(args)
    kw: dict[str, Tensor | TensorOperand] = dict(kwargs)
    for k, v in explicit:
        if v is not None:
            kw[k] = v
    return (tuple(pos), kw)


