    """TensorFlow `raw_ops` namespace."""

    @staticmethod
    def Abort(
        error_msg: Tensor | TensorOperand = None,
        exit_without_error: Tensor | TensorOperand = None,
        name: Tensor | TensorOperand = None,
        *args: Tensor | TensorOperand,
        **kwargs: Tensor | TensorOperand,
    ) -> None:
        """Execute `raw_ops.Abort` operation.

        Args:
            error_msg: Operation parameter `error_msg`.
            exit_without_error: Operation parameter `exit_without_error`.
            name: Operation parameter `name`.
            *args: Additional positional operation arguments.
            **kwargs: Additional keyword operation arguments.

        Returns:
            Tensor | Sequence[Tensor | TensorOperand] | TensorOperand: Operation result.
        """
        del error_msg, exit_without_error, name, args, kwargs
        return None

    @staticmethod
    def Abs(
        x: Tensor | TensorOperand = None,
        name: Tensor | TensorOperand = None,
        *args: Tensor | TensorOperand,
        **kwargs: Tensor | TensorOperand,
    ) -> Tensor | None:
        """Execute `raw_ops.Abs` operation.

        Args:
            x: Operation parameter `x`.
            name: Operation parameter `name`.
            *args: Additional positional operation arguments.
            **kwargs: Additional keyword operation arguments.

        Returns:
            Tensor | Sequence[Tensor | TensorOperand] | TensorOperand: Operation result.
        """
        (args, kwargs) = _pack_raw_call((("x", x), ("name", name)), args, kwargs)
        return _unary_op(_math.abs, args, kwargs)

